                        score = na + nb - 0.1 * (len(cells) - na - nb + 1)
                        if marker is None or score > marker[0]:
                            marker = (score, color, (r, c), a, b)

    if marker is None:
        return grid

    _, key_color, (cr, cc), arm_a, arm_b = marker
    rays = ((-arm_a[0], -arm_a[1]), (-arm_b[0], -arm_b[1]))

    # Find the nearest component lying in the continuation of either arm.
    target = None
    best_score = float("inf")
    for color, cells in comps:
        if color == bg or color == key_color:
            continue
        for r, c in cells:
            dr, dc = r - cr, c - cc
            for vr, vc in rays:
                projection = dr * vr + dc * vc
                if projection <= 0:
                    continue
                perpendicular = abs(dr * vc - dc * vr)
                score = projection + 2 * perpendicular
                if score < best_score:
                    best_score = score
                    target = cells

    out = [row[:] for row in grid]
    if target is not None:
        for r, c in target:
            out[r][c] = key_color
    return out
